// The neural grapheme-to-phoneme (G2P) model's inference - letters to ARPAbet phones with stress, for every word the app
// speaks (no pronouncing dictionary at runtime). The model (lib/g2pModel.js, generated by nn/g2p.py export) is a manifest
// and its quantized weights as base64; loadG2p decodes it once (asynchronously - the weights may be deflated) and returns
// a fast synchronous pronounce function with a per-word cache.
//
// The design ("ctc"): a bidirectional GRU over the letters, each letter repeated "upsample" times plus a position vector,
// a bidirectional GRU over those frames, and greedy CTC decoding (each frame's best, repeats merged, blanks dropped).


// Decode base64 (whitespace ignored) to bytes
export function base64Bytes(text) {
    const binary = atob(text.replace(/\s+/g, ''));
    const bytes = new Uint8Array(binary.length);
    for (let ix = 0; ix < binary.length; ix++) {
        bytes[ix] = binary.charCodeAt(ix);
    }
    return bytes;
}


// Inflate raw-deflated bytes with the built-in DecompressionStream (browsers and Node 18+), as lib/zip.js does
async function inflate(bytes) {
    const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate-raw'));
    return new Uint8Array(await new Response(stream).arrayBuffer());
}


// Unpack the model's tensors from its weight bytes - a Map of name to Float64Array (row-major). The bytes are every
// tensor's scales (bfloat16, one per row or per group of a row), then every tensor's values - signed integers of the
// tensor's bits, offset to unsigned, each tensor starting on a byte - packed little-endian bit by bit ("packed") or a
// byte each ("bytes"). A weight is its integer times its scale.
export function unpackTensors(model, bytes) {
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    const scaleView = new DataView(new ArrayBuffer(4));
    const shapes = model.tensors.map(({shape}) => (shape.length === 1 ? [1, shape[0]] : shape));
    const groupsPerRow = (columns) => (model.groupSize ? Math.ceil(columns / model.groupSize) : 1);
    const groupSize = (columns) => (model.groupSize || columns);

    // The scales
    let offset = 0;
    const scales = shapes.map(([rows, columns]) => {
        const values = new Float64Array(rows * groupsPerRow(columns));
        for (let ix = 0; ix < values.length; ix++) {
            scaleView.setUint32(0, view.getUint16(offset, true) << 16);
            values[ix] = scaleView.getFloat32(0);
            offset += 2;
        }
        return values;
    });

    // The values
    const tensors = new Map();
    for (const [index, {name, bits}] of model.tensors.entries()) {
        const [rows, columns] = shapes[index];
        const values = new Float64Array(rows * columns);
        const zero = (1 << (bits - 1)) - 1;
        let bit = 0;
        for (let ix = 0; ix < values.length; ix++) {
            let unsigned;
            if (model.layout === 'bytes') {
                unsigned = bytes[offset + ix];
            } else {
                unsigned = 0;
                for (let bitIndex = 0; bitIndex < bits; bitIndex++, bit++) {
                    unsigned |= ((bytes[offset + (bit >> 3)] >> (bit & 7)) & 1) << bitIndex;
                }
            }
            const row = Math.floor(ix / columns);
            const group = row * groupsPerRow(columns) + Math.floor((ix % columns) / groupSize(columns));
            values[ix] = (unsigned - zero) * scales[index][group];
        }
        offset += model.layout === 'bytes' ? values.length : Math.ceil(bit / 8);
        tensors.set(name, values);
    }
    return tensors;
}


// The logistic function
function sigmoid(value) {
    return 1 / (1 + Math.exp(-value));
}


// Multiply a row-major matrix [rows, columns] by a vector, plus a bias
function matrixVector(matrix, columns, vector, bias, rows) {
    const result = new Float64Array(rows);
    for (let row = 0; row < rows; row++) {
        let sum = bias[row];
        const base = row * columns;
        for (let column = 0; column < columns; column++) {
            sum += matrix[base + column] * vector[column];
        }
        result[row] = sum;
    }
    return result;
}


// A GRU step (PyTorch's gate order and formula: r, z, n; h' = n + z * (h - n))
function gruStep(gru, input, state) {
    const {hidden} = gru;
    const inputGates = matrixVector(gru.inputWeights, input.length, input, gru.inputBias, 3 * hidden);
    const stateGates = matrixVector(gru.stateWeights, hidden, state, gru.stateBias, 3 * hidden);
    const next = new Float64Array(hidden);
    for (let ix = 0; ix < hidden; ix++) {
        const reset = sigmoid(inputGates[ix] + stateGates[ix]);
        const update = sigmoid(inputGates[hidden + ix] + stateGates[hidden + ix]);
        const candidate = Math.tanh(inputGates[2 * hidden + ix] + reset * stateGates[2 * hidden + ix]);
        next[ix] = candidate + update * (state[ix] - candidate);
    }
    return next;
}


// Run a bidirectional GRU over inputs - each step's output (forward then backward state)
function bidirectional(forward, backward, inputs) {
    const outputs = inputs.map(() => new Float64Array(2 * forward.hidden));
    let state = new Float64Array(forward.hidden);
    for (const [ix, input] of inputs.entries()) {
        state = gruStep(forward, input, state);
        outputs[ix].set(state, 0);
    }
    state = new Float64Array(backward.hidden);
    for (let ix = inputs.length - 1; ix >= 0; ix--) {
        state = gruStep(backward, inputs[ix], state);
        outputs[ix].set(state, backward.hidden);
    }
    return outputs;
}


// The index of the largest value (the first, on ties)
function argmax(values) {
    let best = 0;
    for (let ix = 1; ix < values.length; ix++) {
        if (values[ix] > values[best]) {
            best = ix;
        }
    }
    return best;
}


// A GRU's weights from the tensors by PyTorch name prefix and suffix (for example, "encoder", "_reverse")
function gruWeights(tensors, prefix, suffix, hidden) {
    return {
        hidden,
        'inputWeights': tensors.get(`${prefix}.weight_ih_l0${suffix}`),
        'stateWeights': tensors.get(`${prefix}.weight_hh_l0${suffix}`),
        'inputBias': tensors.get(`${prefix}.bias_ih_l0${suffix}`),
        'stateBias': tensors.get(`${prefix}.bias_hh_l0${suffix}`)
    };
}


// The rows of an embedding table for ids
function embedRows(table, width, ids) {
    return ids.map((id) => table.subarray(id * width, (id + 1) * width));
}


// Pronounce letter ids with the CTC model - phone ids
function pronounceCtc(model, tensors, letterIds) {
    const {embed, hidden, upsample} = model;
    const encoded = bidirectional(
        gruWeights(tensors, 'encoder', '', hidden), gruWeights(tensors, 'encoder', '_reverse', hidden),
        embedRows(tensors.get('letter_embed.weight'), embed, letterIds)
    );
    const position = tensors.get('position');
    const frames = [];
    for (const output of encoded) {
        for (let copy = 0; copy < upsample; copy++) {
            frames.push(output.map((value, ix) => value + position[copy * 2 * hidden + ix]));
        }
    }
    const framed = bidirectional(
        gruWeights(tensors, 'framer', '', hidden), gruWeights(tensors, 'framer', '_reverse', hidden), frames
    );
    const phones = [];
    let previous = 0;
    for (const frame of framed) {
        const logits = matrixVector(tensors.get('output.weight'), 2 * hidden, frame, tensors.get('output.bias'), model.phones.length);
        const best = argmax(logits);
        if (best !== previous && best !== 0) {
            phones.push(best);
        }
        previous = best;
    }
    return phones;
}


// Load a G2P model (lib/g2pModel.js's g2pModel) - returns pronounce(word), the word's ARPAbet phones with stress
// (for example, ['K', 'W', 'IY1', 'K', 'W', 'EH2', 'G']), cached per word
export async function loadG2p(model) {
    let bytes = base64Bytes(model.weights);
    if (model.deflate) {
        bytes = await inflate(bytes);
    }
    const tensors = unpackTensors(model, bytes);
    const letterIds = new Map([...model.letters].map((letter, ix) => [letter, ix + 1]));
    if (model.design !== 'ctc') {
        throw new Error(`Unsupported G2P model design ${model.design}`);
    }
    const cache = new Map();
    return (word) => {
        let phones = cache.get(word);
        if (phones === undefined) {
            const letters = [...word].filter((letter) => letterIds.has(letter)).slice(0, model.maxLetters);
            const ids = letters.map((letter) => letterIds.get(letter));
            phones = ids.length === 0 ? [] : pronounceCtc(model, tensors, ids).map((id) => model.phones[id]);
            cache.set(word, phones);
        }
        return phones;
    };
}
